<?php
declare(strict_types=1);
namespace PlusChat;
use PlusChat\Auth\Auth;use PlusChat\Http\Request;use PlusChat\Http\Response;
final class FileController{
 public function upload(Request $r):Response{$u=Auth::user($r);if(!$u)return Response::json(['error'=>'unauthorized'],401);if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)return Response::json(['error'=>'upload_failed'],400);$f=$_FILES['file'];$max=(int)(getenv('MAX_UPLOAD_BYTES')?:52428800);if((int)$f['size']>$max)return Response::json(['error'=>'file_too_large'],413);$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'])?:'application/octet-stream';$allowed=['image/jpeg','image/png','image/webp','image/gif','video/mp4','audio/mpeg','audio/ogg','audio/webm','application/pdf','text/plain','application/zip'];if(!in_array($mime,$allowed,true))return Response::json(['error'=>'mime_not_allowed'],415);$key=(string)(getenv('FILE_ENCRYPTION_KEY')?:'');$raw=file_get_contents($f['tmp_name']);if(strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES)return Response::json(['error'=>'storage_not_configured'],503);$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$cipher=$nonce.sodium_crypto_secretbox($raw,$nonce,$key);$id=\Ramsey\Uuid\Uuid::uuid4()->toString();$root=rtrim((string)(getenv('PRIVATE_STORAGE_PATH')?:dirname(__DIR__).'/storage'),'/');if(!is_dir($root))mkdir($root,0700,true);$path=$root.'/'.$id.'.bin';file_put_contents($path,$cipher,LOCK_EX);$p=Database::pdo();$dbId=bin2hex(random_bytes(16));$p->prepare('INSERT INTO files(id,owner_id,original_name,mime_type,size_bytes,sha256,storage_path,encrypted) VALUES(:id,:u,:n,:m,:s,:h,:p,TRUE)')->execute(['id'=>$dbId,'u'=>$u['id'],'n'=>basename((string)$f['name']),'m'=>$mime,'s'=>(int)$f['size'],'h'=>hash('sha256',$raw,true),'p'=>$path]);return Response::json(['file_id'=>$dbId,'size'=>(int)$f['size'],'mime'=>$mime],201);}
}
